# Chapter 23 Capacitance — part b: 23.5 to 23.7.


def ser(*cs):
    return 1 / sum(1 / c for c in cs)


def par(*cs):
    return sum(cs)


# ═════════════════════════ 23.5 Comparing capacitors and resistors (17/17/10) ═════════════════════════
lesson('23.5')
M('E', 1, 'Capacitors connected in parallel combine by the same rule as which resistor arrangement?', 'Resistors in series', ['Resistors in parallel', 'A single resistor', 'Resistors connected in a bridge'], 'C = C₁ + C₂ for parallel capacitors has the same form as R = R₁ + R₂ for series resistors.')
N('E', 2, 'A 100 Ω resistor and a 220 Ω resistor are connected in series. Calculate the combined resistance.', 100 + 220, 'Ω',
  'R = R₁ + R₂ = 100 + 220 = 320 Ω', ['C1: resistances add in series'], aq='R')
N('E', 2, 'A 100 µF capacitor and a 220 µF capacitor are connected in series. Calculate the combined capacitance, in µF.', ser(100, 220), 'µF',
  f'C = 100 × 220 ÷ (100 + 220) = {sf(22000 / 320)} µF', ['C1: reciprocal rule for series capacitors'], aq='C')
M('E', 1, 'Which statement correctly compares a capacitor and a resistor in a d.c. circuit?', 'A capacitor stores energy; a resistor dissipates it as heat', ['Both store energy', 'A resistor stores energy; a capacitor dissipates it', 'Neither transfers energy'], 'Charge on the plates stores energy in the field; current through a resistor heats it.')
N('E', 2, 'Two 10 kΩ resistors are connected in parallel. Calculate the combined resistance, in kΩ.', 10 * 10 / 20, 'kΩ',
  'R = 10 × 10 ÷ (10 + 10) = 5.0 kΩ', ['C1: product over sum'], sig=2, aq='R')
N('E', 2, 'A circuit uses two identical 10 µF capacitors side by side, connected in parallel. What capacitance, in µF, do they provide together?', 20, 'µF',
  'Parallel capacitances add: C = 10 + 10 = 20 µF', ['C1: C = C₁ + C₂'], sig=2, aq='C')
M('E', 1, 'A capacitor in series with a resistor is connected to a battery and left for a long time. What is the current in the circuit?', 'Zero', ['The battery e.m.f. divided by the resistance', 'It keeps increasing', 'Half its initial value'], 'Once the capacitor is fully charged its p.d. equals the e.m.f., so there is no p.d. across the resistor and no current.')
M('E', 1, 'Which quantity is the same for each component when resistors are in parallel, and also when capacitors are in parallel?', 'The p.d. across each component', ['The current through each component', 'The charge on each component', 'The energy in each component'], 'Components in parallel are connected between the same two points.')
N('E', 2, 'What single resistor could replace three 30 Ω resistors wired side by side in parallel?', 30 / 3, 'Ω',
  '1/R = 3/30, so R = 30 ÷ 3 = 10 Ω', ['C1: n equal resistors give R/n'], sig=2, aq='R')
M('E', 1, 'One more component is connected in parallel with an existing one. Which row is correct?', 'Total resistance decreases for resistors; total capacitance increases for capacitors', ['Both totals increase', 'Both totals decrease', 'Total resistance increases; total capacitance decreases'], 'An extra parallel path lowers resistance; extra plate area raises capacitance.')
N('E', 2, 'A current of 0.50 A flows through a 20 Ω resistor for 10 s. Calculate the energy dissipated in the resistor.', 0.50 ** 2 * 20 * 10, 'J',
  'W = I²Rt = 0.50² × 20 × 10 = 50 J', ['C1: W = I²Rt'], sig=2, aq='W')
M('E', 1, 'Which pair of units is correct?', 'Ω = V A⁻¹ and F = C V⁻¹', ['Ω = A V⁻¹ and F = V C⁻¹', 'Ω = V A and F = C V', 'Ω = J s⁻¹ and F = J C⁻¹'], 'R = V/I and C = Q/V.')
N('E', 2, 'Three 4.7 µF capacitors are connected in series. Calculate their combined capacitance, in µF.', 4.7 / 3, 'µF',
  f'C = 4.7 ÷ 3 = {sf(4.7 / 3)} µF', ['C1: n equal capacitors in series give C/n'], aq='C')
M('E', 1, 'Which row shows the quantity that is the same for every component connected in series?', 'Resistors: current. Capacitors: charge.', ['Resistors: p.d. Capacitors: p.d.', 'Resistors: current. Capacitors: p.d.', 'Resistors: power. Capacitors: energy.'], 'The same current passes every series resistor; the same charge is moved onto every series capacitor.')
N('E', 1, 'A 1.0 kΩ resistor is joined end to end with another 1.0 kΩ resistor. What is the total resistance, in kΩ?', 2.0, 'kΩ', 'R = 1.0 + 1.0 = 2.0 kΩ', [], sig=2, aq='R')
M('E', 1, 'Which statement about a capacitor and a resistor in a d.c. circuit is correct?', 'A steady current can pass through a resistor, but a capacitor stops a steady current once charged', ['Both allow a steady current', 'Neither allows a steady current', 'A capacitor allows a steady current, but a resistor does not'], 'The dielectric is an insulator, so current flows only while the capacitor\'s charge is changing.')
N('E', 2, 'Calculate the combined capacitance of a 6.0 µF and a 3.0 µF capacitor in series, in µF. (It has the same value as 6.0 Ω and 3.0 Ω resistors in parallel, in Ω.)', ser(6.0, 3.0), 'µF',
  'C = 6.0 × 3.0 ÷ (6.0 + 3.0) = 2.0 µF', ['C1: product over sum'], sig=2, aq='C')
# medium
N('M', 3, 'A 12 V battery charges a 470 µF capacitor through a 2.0 kΩ resistor. Calculate the charge on the capacitor after a long time, in mC.', 470e-6 * 12 * 1000, 'mC',
  f'When fully charged there is no current, so V_C = 12 V. Q = CV = 470 × 10⁻⁶ × 12 = {sf(470e-6 * 12)} C. In mC: {sf(470e-6 * 12, 4)} × 1000 = {sf(470e-6 * 12 * 1000)}', ['B1: no current so V_C = e.m.f.', 'C1: Q = CV'], aq='Q')
N('M', 3, 'A 1.0 kΩ and a 2.0 kΩ resistor are connected in series to a 9.0 V battery. A 100 µF capacitor is connected across the 2.0 kΩ resistor. Calculate the charge on the capacitor once the circuit has settled, in µC.', 100 * 9.0 * 2.0 / 3.0, 'µC',
  'No current flows into the charged capacitor, so the resistors form a potential divider: V = 9.0 × 2.0 ÷ 3.0 = 6.0 V. Q = 100 × 10⁻⁶ × 6.0 = 6.0 × 10⁻⁴ C. In µC: 6.0 × 10⁻⁴ × 10⁶ = 600', ['C1: potential divider', 'C1: Q = CV'], sig=2, aq='Q')
M('M', 3, 'A capacitor and resistor in series are connected to a battery. A long time later, what are the p.d.s across them?', 'Capacitor: equal to the e.m.f. Resistor: zero.', ['Capacitor: zero. Resistor: equal to the e.m.f.', 'Each has half the e.m.f.', 'Both equal the e.m.f.'], 'With no current, V_R = IR = 0, so all the e.m.f. appears across the capacitor.', ['C1: I = 0 when charged', 'C1: V_C = e.m.f.'])
N('M', 4, 'A 3.0 µF and a 6.0 µF capacitor are connected in series across 12 V. Separately, 3.0 Ω and 6.0 Ω resistors are connected in parallel across 12 V. Calculate the charge on each capacitor, in µC.', ser(3.0, 6.0) * 12, 'µC',
  'Series capacitors: C = 3.0 × 6.0 ÷ 9.0 = 2.0 µF; Q = 2.0 × 10⁻⁶ × 12 = 2.4 × 10⁻⁵ C. In µC: 2.4 × 10⁻⁵ × 10⁶ = 24. (The resistors give R = 2.0 Ω and I = 6.0 A: the same number, by the same rule.)', ['C1: reciprocal rule for capacitors', 'C1: Q = CV', 'B1: same form as parallel resistors'], sig=2, aq='Q')
N('M', 3, 'A 100 µF capacitor charged to 10 V stores some energy. A 1.0 kΩ resistor connected across a 10 V supply dissipates energy steadily. How long does the resistor take to dissipate the same energy as the capacitor stores?', 0.5 * 100e-6 * 100 / (10 ** 2 / 1000), 's',
  'W = 0.5 × 100 × 10⁻⁶ × 10² = 5.0 × 10⁻³ J. P = V²/R = 10² ÷ 1000 = 0.10 W. t = 5.0 × 10⁻³ ÷ 0.10 = 0.050 s', ['C1: W = ½CV²', 'C1: P = V²/R', 'C1: t = W/P'], sig=2, aq='t')
M('M', 3, 'The plates of a parallel-plate capacitor are made twice as large in area. The cross-sectional area of a resistance wire is also doubled. Which row is correct?', 'Capacitance doubles; resistance halves', ['Capacitance halves; resistance doubles', 'Both double', 'Both halve'], 'C = εA/d ∝ A; R = ρL/A ∝ 1/A.', ['C1: C ∝ A', 'C1: R ∝ 1/A'])
N('M', 3, 'A 1.5 kΩ resistor and an uncharged capacitor are connected in parallel directly across a 6.0 V battery of negligible internal resistance. Calculate the current in the resistor once the capacitor has charged, in mA.', 6.0 / 1.5e3 * 1000, 'mA',
  'The resistor always has the full 6.0 V across it: I = V/R = 6.0 ÷ 1500 = 4.0 × 10⁻³ A. In mA: 4.0 × 10⁻³ × 1000 = 4.0', ['C1: same p.d. in parallel', 'C1: I = V/R'], sig=2, aq='I')
M('M', 4, 'Three identical capacitors are to be connected together. Which arrangement gives the largest combined capacitance?', 'All three in parallel', ['All three in series', 'Two in series, in parallel with the third', 'Two in parallel, in series with the third'], 'Parallel gives 3C; the others give C/3, 1.5C and 2C/3.', ['C1: parallel adds', 'C1: series reduces', 'C1: compares all four'])
N('M', 3, 'A 2.0 µF capacitor is connected in series with two 4.0 µF capacitors that are in parallel with each other. Calculate the combined capacitance, in µF. (2.0 Ω, 4.0 Ω and 4.0 Ω resistors arranged the same way would give 4.0 Ω.)', ser(2.0, 8.0), 'µF',
  'Parallel pair: 4.0 + 4.0 = 8.0 µF. With 2.0 µF in series: C = 2.0 × 8.0 ÷ 10 = 1.6 µF', ['C1: parallel pair first', 'C1: series with 2.0 µF'], sig=2, aq='C')
N('M', 4, 'A 5.0 V supply is connected across a 1.0 kΩ resistor in series with a 3.3 kΩ resistor. A 10 µF capacitor is connected in parallel with the 3.3 kΩ resistor. Calculate the charge on the capacitor once the circuit has settled, in µC.', 10 * 5.0 * 3.3 / 4.3, 'µC',
  f'No current enters the charged capacitor, so I = 5.0 ÷ 4300 = {sf(5 / 4300)} A and V = 5.0 × 3.3 ÷ 4.3 = {sf(5 * 3.3 / 4.3)} V. Q = 10 × 10⁻⁶ × {sf(5 * 3.3 / 4.3, 4)} = {sf(10e-6 * 5 * 3.3 / 4.3)} C. In µC: {sf(10e-6 * 5 * 3.3 / 4.3, 4)} × 10⁶ = {sf(10 * 5 * 3.3 / 4.3)}', ['B1: capacitor branch carries no steady current', 'C1: p.d. across 3.3 kΩ', 'C1: Q = CV'], aq='Q')
M('M', 3, 'An uncharged capacitor in series with a resistor is switched onto a battery. What are the p.d.s immediately after the switch is closed?', 'Capacitor: zero. Resistor: equal to the e.m.f.', ['Capacitor: equal to the e.m.f. Resistor: zero.', 'Each has half the e.m.f.', 'Both are zero'], 'A capacitor\'s p.d. depends on its charge, which cannot change instantly; at first all the e.m.f. is across R.', ['C1: V_C = Q/C = 0 initially', 'C1: V_R = e.m.f.'])
N('M', 4, 'An uncharged capacitor is connected in series with a 4.7 kΩ resistor to a 12 V battery. Calculate the charging current at the instant the switch is closed, in mA.', 12 / 4.7e3 * 1000, 'mA',
  f'Initially V_C = 0, so all 12 V is across the resistor: I = 12 ÷ 4700 = {sf(12 / 4700)} A. In mA: {sf(12 / 4700, 4)} × 1000 = {sf(12 / 4700 * 1000)}', ['B1: V_C = 0 at the start', 'C1: I = V/R', 'C1: conversion to mA'], aq='I')
M('M', 3, 'Which pair of combinations both give a total that is smaller than any single component?', 'Capacitors in series and resistors in parallel', ['Capacitors in parallel and resistors in series', 'Capacitors in series and resistors in series', 'Capacitors in parallel and resistors in parallel'], 'Both use the reciprocal-sum rule, which always gives less than the smallest value.', ['C1: reciprocal rule', 'C1: identifies both cases'])
N('M', 3, 'How many 1.0 kΩ resistors must be connected in parallel to give a combined resistance of 250 Ω?', 1000 / 250, None,
  'n equal resistors in parallel give R/n, so n = 1000 ÷ 250 = 4', ['C1: R_total = R/n', 'C1: rearranged'], sig=1, aq='n')
N('M', 3, 'A 2200 µF capacitor is charged to 12 V through a resistor by a 12 V battery. Calculate the energy dissipated in the resistor.', 0.5 * 2200e-6 * 12 ** 2, 'J',
  f'The battery supplies QV = CV² and the capacitor stores ½CV², so the resistor dissipates the other half: 0.5 × 2200 × 10⁻⁶ × 12² = {sf(0.5 * 2200e-6 * 144)} J', ['M1: energy dissipated = ½CV²', 'C1: substitution'], aq='W')
M('M', 3, 'Why does a steady current stop in a capacitor branch of a d.c. circuit, but not in a resistor branch?', 'The capacitor\'s dielectric is an insulator, so charge builds up on its plates until their p.d. opposes the supply', ['The capacitor\'s resistance gradually increases to infinity', 'The capacitor uses up the current', 'The resistor stores charge, so it keeps conducting'], 'Charge cannot cross the dielectric; current only flows while the plates are charging.', ['C1: insulating dielectric', 'C1: build-up of p.d. opposes supply'])
N('M', 4, 'A 6.0 µF and a 3.0 µF capacitor in series are connected across 9.0 V. Separately, a 6.0 Ω and a 3.0 Ω resistor in series are connected across 9.0 V. Calculate the p.d. across the 6.0 µF capacitor.', 9.0 * 3.0 / 9.0, 'V',
  'Same charge on each capacitor, so V ∝ 1/C: V₆ = 9.0 × 3.0 ÷ (6.0 + 3.0) = 3.0 V. (The 6.0 Ω resistor takes 6.0 V instead: for resistors V ∝ R.)', ['C1: same Q', 'M1: V ∝ 1/C', 'B1: contrast with V ∝ R'], sig=2, aq='V')
# hard
N('H', 6, 'A 12 V battery is connected across a 2.0 kΩ resistor R₁ in series with a 4.0 kΩ resistor R₂. A 10 µF capacitor is connected across R₁ and a 20 µF capacitor across R₂. (a) Explain why no current flows into either capacitor once the circuit has settled. (b) Calculate the p.d. across each capacitor. (c) Calculate the charge on the 20 µF capacitor, in µC. (d) Calculate the total energy stored. Give only the answer to (c).', 20 * 12 * 4.0 / 6.0, 'µC',
  '(a) Once charged, the capacitors\' p.d.s equal those across the resistors, and no charge can cross a dielectric. (b) I = 12 ÷ 6000 = 2.0 × 10⁻³ A; V₁ = 2.0 × 10⁻³ × 2000 = 4.0 V and V₂ = 2.0 × 10⁻³ × 4000 = 8.0 V. (c) Q = 20 × 10⁻⁶ × 8.0 = 1.6 × 10⁻⁴ C. In µC: 1.6 × 10⁻⁴ × 10⁶ = 160. (d) W = 0.5 × 10 × 10⁻⁶ × 4.0² + 0.5 × 20 × 10⁻⁶ × 8.0² = 7.2 × 10⁻⁴ J',
  ['B1: no steady current into capacitors', 'C1: potential divider', 'C1: V across each', 'C1: Q = CV', 'C1: total energy'], sig=2, aq='Q')
N('H', 5, 'Three components, each of value 6.0 (6.0 Ω for resistors or 6.0 µF for capacitors), are connected with two in parallel and that pair in series with the third. (a) Calculate the combined resistance for three resistors. (b) Calculate the combined capacitance for three capacitors, in µF. (c) Explain why the two answers are different although the arrangement is the same. Give only the answer to (b).', ser(12.0, 6.0), 'µF',
  '(a) Parallel pair 3.0 Ω, in series with 6.0 Ω: R = 3.0 + 6.0 = 9.0 Ω. (b) Parallel pair 12 µF, in series with 6.0 µF: C = 12 × 6.0 ÷ 18 = 4.0 µF. (c) The rules are reversed: capacitors add in parallel but resistors add in series.',
  ['C1: resistor network', 'C1: parallel capacitors add', 'C1: series capacitors by reciprocal rule', 'B1: rules swapped for C and R'], sig=2, aq='C')
N('H', 6, 'A 470 µF capacitor is charged from 0 to 9.0 V through a resistor R by a 9.0 V battery. (a) Calculate the energy supplied by the battery. (b) Calculate the energy stored in the capacitor. (c) Calculate the energy dissipated in the resistor, in mJ. (d) Explain why the answer to (c) does not depend on the value of R. Give only the answer to (c).', 0.5 * 470e-6 * 81 * 1000, 'mJ',
  f'(a) Q = 470 × 10⁻⁶ × 9.0 = {sf(470e-6 * 9)} C; W = QV = {sf(470e-6 * 9, 4)} × 9.0 = {sf(470e-6 * 81)} J. (b) ½QV = 0.5 × {sf(470e-6 * 9, 4)} × 9.0 = {sf(0.5 * 470e-6 * 81)} J. (c) {sf(470e-6 * 81, 4)} − {sf(0.5 * 470e-6 * 81, 4)} = {sf(0.5 * 470e-6 * 81)} J. In mJ: {sf(0.5 * 470e-6 * 81, 4)} × 1000 = {sf(0.5 * 470e-6 * 81 * 1000)}. (d) The same charge passes through R whatever its value; R only changes how quickly the charging happens.',
  ['C1: W = QV from battery', 'C1: ½QV stored', 'M1: difference dissipated', 'C1: conversion to mJ', 'B1: independent of R, only time changes'], aq='W')
N('H', 6, 'A 6.0 V battery is connected across two parallel branches. Branch 1 is a 1.0 kΩ resistor in series with a 2.0 kΩ resistor, with the 2.0 kΩ resistor connected to the negative terminal. Branch 2 is a 2.0 µF capacitor in series with a 4.0 µF capacitor, with the 4.0 µF capacitor connected to the negative terminal. A high-resistance voltmeter is connected between the midpoints of the two branches. (a) Calculate the p.d. across the 2.0 kΩ resistor. (b) Calculate the p.d. across the 4.0 µF capacitor. (c) Calculate the voltmeter reading. Give only the answer to (c).', 6.0 * 2.0 / 3.0 - 6.0 * 2.0 / 6.0, 'V',
  '(a) Potential divider: 6.0 × 2.0 ÷ 3.0 = 4.0 V. (b) Same charge on both capacitors, so V ∝ 1/C: 6.0 × 2.0 ÷ (2.0 + 4.0) = 2.0 V. (c) The midpoints are 4.0 V and 2.0 V above the negative terminal: reading = 4.0 − 2.0 = 2.0 V',
  ['C1: resistor divider V ∝ R', 'M1: capacitor divider V ∝ 1/C', 'C1: p.d. across 4.0 µF', 'C1: difference of potentials', 'B1: explains which side is higher'], sig=2, aq='V')
N('H', 5, 'A real 100 µF capacitor can be modelled as an ideal capacitor in parallel with a 10 MΩ "leakage" resistance. It is charged to 12 V and disconnected. (a) Calculate the initial leakage current, in µA. (b) Calculate the initial charge. (c) Estimate the time for the capacitor to lose 1 % of its charge, assuming the current stays roughly constant. Give only the answer to (a).', 12 / 10e6 * 1e6, 'µA',
  '(a) I = V/R = 12 ÷ 10 × 10⁶ = 1.2 × 10⁻⁶ A. In µA: 1.2 × 10⁻⁶ × 10⁶ = 1.2. (b) Q = 100 × 10⁻⁶ × 12 = 1.2 × 10⁻³ C. (c) 1 % of Q = 1.2 × 10⁻⁵ C; t = 1.2 × 10⁻⁵ ÷ 1.2 × 10⁻⁶ = 10 s',
  ['C1: I = V/R', 'C1: Q = CV', 'C1: 1 % of Q', 'C1: t = ΔQ/I'], sig=2, aq='I')
N('H', 6, 'A 2.0 µF and an 8.0 µF capacitor are connected in series across a 100 V supply. (a) Calculate the p.d. across each capacitor. (b) A 1.0 MΩ resistor is now connected in parallel with each capacitor. Explain why, after a long time, the p.d.s become 50 V each. (c) Calculate the charge on the 2.0 µF capacitor in this new steady state, in µC. Give only the p.d. across the 2.0 µF capacitor from (a).', 100 * 8.0 / 10.0, 'V',
  '(a) Same charge, so V ∝ 1/C: V₂ = 100 × 8.0 ÷ (2.0 + 8.0) = 80 V and V₈ = 20 V. (b) In the steady state a current flows through the two equal resistors, which share the 100 V equally, and each capacitor takes the p.d. of the resistor across it. (c) Q = 2.0 × 10⁻⁶ × 50 = 1.0 × 10⁻⁴ C, which is 100 µC.',
  ['M1: V ∝ 1/C in series', 'C1: 80 V and 20 V', 'B1: resistors set the steady p.d.s', 'B1: equal resistors share equally', 'C1: Q = CV'], sig=2, aq='V')
N('H', 5, 'A battery of e.m.f. 12 V and internal resistance 0.50 Ω is connected to a 5.5 Ω resistor. A 1000 µF capacitor is connected directly across the battery terminals. (a) Calculate the current. (b) Calculate the terminal p.d. (c) Calculate the charge on the capacitor, in mC. (d) State the charge on the capacitor if the 5.5 Ω resistor were removed. Give only the answer to (c).', 1000e-6 * 12 * 5.5 / 6.0 * 1000, 'mC',
  '(a) I = 12 ÷ (5.5 + 0.50) = 2.0 A. (b) V = 12 − 2.0 × 0.50 = 11 V. (c) Q = 1000 × 10⁻⁶ × 11 = 0.011 C. In mC: 0.011 × 1000 = 11. (d) With no current, V = e.m.f. = 12 V, so Q = 12 mC.',
  ['C1: I = E/(R + r)', 'C1: terminal p.d.', 'C1: Q = CV', 'B1: 12 mC with no current'], sig=2, aq='Q')
N('H', 6, 'An uncharged 47 µF capacitor is connected in series with a 10 kΩ resistor to a 9.0 V battery. (a) Calculate the initial current. (b) Calculate the initial rate at which the p.d. across the capacitor rises, in V s⁻¹. (c) Explain why this rate decreases as the capacitor charges. Give only the answer to (b).', (9.0 / 10e3) / 47e-6, 'V s⁻¹',
  f'(a) I₀ = 9.0 ÷ 10 000 = 9.0 × 10⁻⁴ A. (b) I = dQ/dt = C dV/dt, so dV/dt = 9.0 × 10⁻⁴ ÷ 47 × 10⁻⁶ = {sf(9e-4 / 47e-6)} V s⁻¹. (c) As V_C rises, the p.d. across the resistor and hence the current fall, so charge, and p.d., are added more slowly.',
  ['C1: I₀ = E/R', 'M1: I = C dV/dt', 'C1: substitution', 'B1: current falls as V_C rises', 'C1: units V s⁻¹'], aq='dV/dt')
N('H', 5, '(a) Explain why resistances add in series but capacitances add in parallel, by stating what is common to the components in each case. (b) Calculate the combined resistance of 3.3 kΩ and 4.7 kΩ resistors in series. (c) Calculate the combined capacitance of 3.3 µF and 4.7 µF capacitors in series, in µF. Give only the answer to (c).', ser(3.3, 4.7), 'µF',
  f'(a) Series resistors carry the same current and their p.d.s add, so R = V/I adds. Parallel capacitors share the same p.d. and their charges add, so C = Q/V adds. (b) R = 3.3 + 4.7 = 8.0 kΩ. (c) C = 3.3 × 4.7 ÷ (3.3 + 4.7) = {sf(3.3 * 4.7 / 8)} µF',
  ['B1: common current in series resistors', 'B1: common p.d. in parallel capacitors', 'C1: series resistance', 'C1: series capacitance'], aq='C')
N('H', 6, 'A 12 V battery is connected in series with a 10 kΩ resistor to a 220 µF capacitor. A 20 kΩ resistor is connected in parallel with the capacitor. (a) Explain why a steady current still flows when the capacitor is fully charged. (b) Calculate this steady current. (c) Calculate the final p.d. across the capacitor. (d) Calculate the final charge on the capacitor, in mC. Give only the answer to (d).', 220e-6 * 12 * 20 / 30 * 1000, 'mC',
  '(a) Current can still pass through the 20 kΩ resistor, which is a parallel path around the capacitor. (b) I = 12 ÷ 30 000 = 4.0 × 10⁻⁴ A. (c) V = 4.0 × 10⁻⁴ × 20 000 = 8.0 V. (d) Q = 220 × 10⁻⁶ × 8.0 = 1.76 × 10⁻³ C. In mC: 1.76 × 10⁻³ × 1000 = 1.76',
  ['B1: path through parallel resistor', 'C1: I = E/R_total', 'C1: V across 20 kΩ', 'C1: Q = CV', 'C1: conversion to mC'], aq='Q')

# ═════════════════════════ 23.6 Capacitor networks (17/20/7) ═════════════════════════
lesson('23.6')
N('E', 2, 'A 2.0 µF and a 3.0 µF capacitor are in parallel, and the pair is in series with a 5.0 µF capacitor. Calculate the combined capacitance, in µF.', ser(5.0, 5.0), 'µF',
  'Parallel pair: 2.0 + 3.0 = 5.0 µF. In series with 5.0 µF: C = 5.0 × 5.0 ÷ 10 = 2.5 µF', ['C1: reduce the parallel pair first'], sig=2, aq='C')
N('E', 2, 'A branch of two 4.0 µF capacitors in series has a 2.0 µF capacitor connected across it. What is the total, in µF?', 2.0 + 2.0, 'µF',
  'Series pair: 4.0 ÷ 2 = 2.0 µF. In parallel with 2.0 µF: C = 2.0 + 2.0 = 4.0 µF', ['C1: series pair then parallel'], sig=2, aq='C')
M('E', 1, 'What is the best first step when finding the combined capacitance of a network?', 'Replace each group that is clearly in series or clearly in parallel with a single equivalent capacitor', ['Add all the capacitances together', 'Use the reciprocal rule for every capacitor', 'Start with the capacitor nearest the positive terminal'], 'Simplify the innermost groups step by step until one capacitor remains.')
N('E', 2, 'Three 3.0 µF capacitors are connected so that two are in series and that pair is in parallel with the third. Calculate the combined capacitance, in µF.', 1.5 + 3.0, 'µF',
  'Series pair: 3.0 ÷ 2 = 1.5 µF. Total: 1.5 + 3.0 = 4.5 µF', ['C1: series pair then add'], sig=2, aq='C')
N('E', 2, 'A 3.0 µF capacitor is connected in series with a parallel pair of 3.0 µF capacitors. Find the equivalent capacitance, in µF.', ser(6.0, 3.0), 'µF',
  'Parallel pair: 6.0 µF. In series with 3.0 µF: C = 6.0 × 3.0 ÷ 9.0 = 2.0 µF', ['C1: parallel pair then series'], sig=2, aq='C')
M('E', 1, 'Three identical capacitors can be connected in four different ways. Which arrangement gives the smallest combined capacitance?', 'All three in series', ['All three in parallel', 'Two in series, in parallel with the third', 'Two in parallel, in series with the third'], 'All in series gives C/3, the smallest of C/3, 2C/3, 1.5C and 3C.')
N('E', 2, 'A network has two 10 µF capacitors in parallel with each other, and also in parallel with a branch made of two 10 µF capacitors in series. Calculate the combined capacitance, in µF.', 10 + 10 + 5, 'µF',
  'Series branch: 10 ÷ 2 = 5.0 µF. Total: 10 + 10 + 5.0 = 25 µF', ['C1: series branch then add parallel paths'], sig=2, aq='C')
M('E', 1, 'Two 2.0 µF capacitors are to give a combined capacitance of 1.0 µF. How must they be connected?', 'In series', ['In parallel', 'One alone, with the other disconnected', 'It cannot be done'], 'Two equal capacitors in series give half the value.')
N('E', 2, 'Two 1.0 µF capacitors in parallel are connected in series with another two 1.0 µF capacitors in parallel. Calculate the combined capacitance, in µF.', ser(2.0, 2.0), 'µF',
  'Each parallel pair is 2.0 µF; two in series give 2.0 ÷ 2 = 1.0 µF', ['C1: reduce each pair'], sig=2, aq='C')
N('E', 2, 'A capacitor network that is equivalent to 4.5 µF is placed across 10 V. How much charge, in µC, leaves the supply?', 4.5 * 10, 'µC',
  'Q = CV = 4.5 × 10⁻⁶ × 10 = 4.5 × 10⁻⁵ C. In µC: 4.5 × 10⁻⁵ × 10⁶ = 45', ['C1: Q = C_total V'], sig=2, aq='Q')
M('E', 1, 'Three identical capacitors, each of capacitance C, are connected with two in series and that pair in parallel with the third. What is the combined capacitance?', '1.5C', ['3C', 'C/3', '2C/3'], 'Series pair C/2, plus C in parallel: 1.5C.')
N('E', 2, 'A 6.0 µF capacitor is in series with a parallel pair made of a 2.0 µF and a 4.0 µF capacitor. Calculate the combined capacitance, in µF.', ser(6.0, 6.0), 'µF',
  'Parallel pair: 2.0 + 4.0 = 6.0 µF. In series with 6.0 µF: C = 6.0 ÷ 2 = 3.0 µF', ['C1: parallel then series'], sig=2, aq='C')
M('E', 1, 'In a network, two capacitors are connected between the same pair of junctions. What is the same for both?', 'The p.d. across them', ['The charge on them', 'The energy stored in them', 'Their capacitance'], 'Components between the same two junctions are in parallel.')
N('E', 2, 'What is the equivalent capacitance, in µF, of a 100 µF capacitor in series with the parallel combination of 22 µF and 47 µF?', ser(69, 100), 'µF',
  f'Parallel pair: 22 + 47 = 69 µF. In series with 100 µF: C = 69 × 100 ÷ 169 = {sf(6900 / 169)} µF', ['C1: parallel then series'], aq='C')
N('E', 1, 'Four 8.0 µF capacitors are arranged as two series pairs, and the pairs are connected side by side. Find the total capacitance, in µF.', 4.0 + 4.0, 'µF',
  'Each series pair is 4.0 µF; in parallel: 4.0 + 4.0 = 8.0 µF', [], sig=2, aq='C')
M('E', 1, 'What is (capacitance of three identical capacitors in parallel) ÷ (capacitance of the same three in series)?', '9', ['3', '1', '1/9'], 'Parallel 3C; series C/3; ratio 9.')
N('E', 2, 'A network that behaves as 2.0 µF is charged by a 50 V supply. What energy does it store, in mJ?', 0.5 * 2.0e-6 * 50 ** 2 * 1000, 'mJ',
  'W = ½CV² = 0.5 × 2.0 × 10⁻⁶ × 50² = 2.5 × 10⁻³ J. In mJ: 2.5 × 10⁻³ × 1000 = 2.5', ['C1: W = ½CV²'], sig=2, aq='W')
# medium
N('M', 3, 'A 2.0 µF and a 4.0 µF capacitor in parallel are connected in series with a 3.0 µF capacitor across 12 V. Calculate the p.d. across the 3.0 µF capacitor.', ser(6.0, 3.0) * 12 / 3.0, 'V',
  'Parallel pair 6.0 µF; total C = 6.0 × 3.0 ÷ 9.0 = 2.0 µF. Q = 2.0 × 10⁻⁶ × 12 = 2.4 × 10⁻⁵ C. V₃ = 2.4 × 10⁻⁵ ÷ 3.0 × 10⁻⁶ = 8.0 V', ['C1: total C', 'C1: Q = CV', 'C1: V = Q/C for the series capacitor'], sig=2, aq='V')
N('M', 3, 'In a network, a 2.0 µF and a 4.0 µF capacitor are in parallel, and the pair is in series with a 3.0 µF capacitor across 12 V. The p.d. across the 3.0 µF capacitor is 8.0 V. Calculate the charge on the 4.0 µF capacitor, in µC.', 4.0 * (12 - 8.0), 'µC',
  'p.d. across the parallel pair: 12 − 8.0 = 4.0 V. Q = 4.0 × 10⁻⁶ × 4.0 = 1.6 × 10⁻⁵ C. In µC: 1.6 × 10⁻⁵ × 10⁶ = 16', ['C1: p.d.s add to 12 V', 'C1: Q = CV'], sig=2, aq='Q')
N('M', 4, 'A branch of a 6.0 µF capacitor in series with a 3.0 µF capacitor is connected in parallel with a 4.0 µF capacitor, across a 9.0 V supply. Calculate the charge on the 3.0 µF capacitor, in µC.', ser(6.0, 3.0) * 9.0, 'µC',
  'Each branch has 9.0 V across it. Series branch: C = 6.0 × 3.0 ÷ 9.0 = 2.0 µF, so Q = 2.0 × 10⁻⁶ × 9.0 = 1.8 × 10⁻⁵ C on each of its capacitors. In µC: 1.8 × 10⁻⁵ × 10⁶ = 18', ['B1: each branch has the full 9.0 V', 'C1: series branch C', 'C1: Q = CV'], sig=2, aq='Q')
M('M', 3, 'Two capacitors are in series. A third capacitor is then connected in parallel with one of them. What happens to the combined capacitance?', 'It increases', ['It decreases', 'It stays the same', 'It becomes zero'], 'The parallel pair has a larger capacitance, so the series combination increases.', ['C1: parallel pair larger', 'C1: series total larger'])
N('M', 3, 'An unknown capacitor X is in series with a 6.0 µF capacitor, and a 2.0 µF capacitor is connected in parallel with this series pair. The combined capacitance is 5.0 µF. Calculate X, in µF.', 1 / (1 / 3.0 - 1 / 6.0), 'µF',
  'The series pair must be 5.0 − 2.0 = 3.0 µF. 1/X = 1/3.0 − 1/6.0, so X = 1 ÷ (1/3.0 − 1/6.0) = 6.0 µF', ['C1: series pair = 3.0 µF', 'C1: reciprocal rule rearranged'], sig=2, aq='X')
N('M', 4, 'A 3.0 µF capacitor is in series with a parallel pair of two 3.0 µF capacitors, across 12 V. Calculate the energy stored in the single 3.0 µF capacitor, in µJ.', (ser(3.0e-6, 6.0e-6) * 12) ** 2 / (2 * 3.0e-6) * 1e6, 'µJ',
  'Parallel pair 6.0 µF; total C = 3.0 × 6.0 ÷ 9.0 = 2.0 µF; Q = 2.0 × 10⁻⁶ × 12 = 2.4 × 10⁻⁵ C. W = Q²/2C = (2.4 × 10⁻⁵)² ÷ (2 × 3.0 × 10⁻⁶) = 9.6 × 10⁻⁵ J. In µJ: 9.6 × 10⁻⁵ × 10⁶ = 96', ['C1: total C', 'C1: same Q on series capacitor', 'C1: W = Q²/2C'], sig=2, aq='W')
M('M', 3, 'A 2.0 µF capacitor is in series with a parallel pair made of a 6.0 µF and a 4.0 µF capacitor. Which capacitor has the largest p.d. across it when the network is connected to a supply?', 'The 2.0 µF capacitor', ['The 6.0 µF capacitor', 'The 4.0 µF capacitor', 'All have the same p.d.'], 'The parallel pair is 10 µF; in series, the smaller 2.0 µF takes five times the p.d. of the pair.', ['C1: parallel pair 10 µF', 'C1: V ∝ 1/C in series'])
N('M', 3, 'Using a 1.0 µF, a 2.0 µF and a 3.0 µF capacitor, all three must be used. Calculate the smallest combined capacitance possible, in µF.', ser(1.0, 2.0, 3.0), 'µF',
  f'All in series: C = 1 ÷ (1/1.0 + 1/2.0 + 1/3.0) = {sf(1 / (1 + 0.5 + 1 / 3))} µF', ['M1: all in series gives the smallest', 'C1: reciprocal sum'], aq='C')
N('M', 3, 'Two 10 µF capacitors in series are connected in parallel with another two 10 µF capacitors in series, and the network is connected across 20 V. Calculate the total energy stored, in mJ.', 0.5 * 10e-6 * 20 ** 2 * 1000, 'mJ',
  'Each branch 5.0 µF; total 10 µF. W = 0.5 × 10 × 10⁻⁶ × 20² = 2.0 × 10⁻³ J. In mJ: 2.0 × 10⁻³ × 1000 = 2.0', ['C1: total C = 10 µF', 'C1: W = ½CV²'], sig=2, aq='W')
M('M', 4, 'When are two capacitors in a network in series with each other?', 'When they are joined at a junction to which nothing else is connected, so the same charge must flow onto both', ['Whenever they are drawn one after the other on the diagram', 'Whenever they have the same capacitance', 'Whenever they are connected to the same supply'], 'Series requires a single path: the joining node must have no other branch.', ['C1: single junction with no other branch', 'C1: same charge', 'C1: drawing position irrelevant'])
N('M', 3, 'Two 1.0 µF capacitors in series are connected in parallel with a 1.0 µF capacitor, and this combination is in series with a 1.5 µF capacitor. Calculate the combined capacitance, in µF.', ser(1.5, 1.5), 'µF',
  'Series pair 0.50 µF; parallel with 1.0 µF gives 1.5 µF; in series with 1.5 µF: 1.5 ÷ 2 = 0.75 µF', ['C1: inner reductions', 'C1: final series step'], sig=2, aq='C')
N('M', 4, 'A 4.0 µF capacitor C₁ is in series with a parallel pair C₂ = 2.0 µF and C₃ = 2.0 µF, across a 12 V supply. Calculate the charge on C₂, in µC.', 2.0 * (12 - ser(4.0, 4.0) * 12 / 4.0), 'µC',
  'Parallel pair 4.0 µF; total C = 2.0 µF; Q = 2.0 × 10⁻⁶ × 12 = 2.4 × 10⁻⁵ C. V₁ = 2.4 × 10⁻⁵ ÷ 4.0 × 10⁻⁶ = 6.0 V, so the pair has 6.0 V. Q₂ = 2.0 × 10⁻⁶ × 6.0 = 1.2 × 10⁻⁵ C. In µC: 1.2 × 10⁻⁵ × 10⁶ = 12', ['C1: total C', 'C1: p.d. across C₁', 'C1: p.d. across pair', 'C1: Q₂ = C₂V'], sig=2, aq='Q₂')
M('M', 3, 'A network is connected across a fixed supply. A new capacitor is connected directly across the supply, in parallel with the whole network. What happens to the charges on the original capacitors?', 'They stay the same', ['They all increase', 'They all decrease', 'They become zero'], 'The p.d. across the original network is still the supply p.d., so its charges are unchanged.', ['C1: p.d. across network unchanged', 'C1: Q = CV unchanged'])
N('M', 3, 'A 4.7 µF capacitor is connected in parallel with a branch of two 4.7 µF capacitors in series. Calculate the combined capacitance, in µF.', 4.7 + 4.7 / 2, 'µF',
  f'Series branch: 4.7 ÷ 2 = 2.35 µF. Total: 4.7 + 2.35 = {sf(4.7 + 2.35)} µF', ['C1: series branch', 'C1: add parallel'], aq='C')
N('M', 3, 'A 3.0 µF capacitor is in series with a parallel pair of a 6.0 µF and a 3.0 µF capacitor, across 24 V. Calculate the p.d. across the single 3.0 µF capacitor.', ser(3.0, 9.0) * 24 / 3.0, 'V',
  'Parallel pair 9.0 µF; total C = 3.0 × 9.0 ÷ 12 = 2.25 µF; Q = 2.25 × 10⁻⁶ × 24 = 5.4 × 10⁻⁵ C. V = 5.4 × 10⁻⁵ ÷ 3.0 × 10⁻⁶ = 18 V', ['C1: total C', 'C1: Q = CV', 'C1: V = Q/C'], sig=2, aq='V')
M('M', 3, 'One capacitor in a series chain develops a short circuit. What happens to the combined capacitance of the chain?', 'It increases', ['It decreases', 'It stays the same', 'It becomes zero'], 'Removing a term from the reciprocal sum makes 1/C smaller, so C rises.', ['C1: fewer series capacitors', 'C1: total rises'])
N('M', 4, 'A 3.0 µF capacitor is in series with a parallel pair of a 6.0 µF and a 3.0 µF capacitor, across 24 V; the series 3.0 µF capacitor has 18 V across it. Calculate the energy stored in the 6.0 µF capacitor, in µJ.', 0.5 * 6.0e-6 * (24 - 18) ** 2 * 1e6, 'µJ',
  'p.d. across the parallel pair: 24 − 18 = 6.0 V. W = 0.5 × 6.0 × 10⁻⁶ × 6.0² = 1.08 × 10⁻⁴ J. In µJ: 1.08 × 10⁻⁴ × 10⁶ = 108', ['C1: p.d. across parallel pair', 'C1: W = ½CV²', 'C1: conversion'], aq='W')
N('M', 3, 'Three identical capacitors are connected with two in series and that pair in parallel with the third. The combined capacitance is 6.0 µF. Calculate the capacitance of each, in µF.', 6.0 / 1.5, 'µF',
  'Combined = C/2 + C = 1.5C, so C = 6.0 ÷ 1.5 = 4.0 µF', ['C1: 1.5C', 'C1: rearranged'], sig=2, aq='C')
M('M', 3, 'Four identical capacitors, each C, are to give a combined capacitance of C. Which arrangement does this?', 'Two series pairs connected in parallel', ['All four in parallel', 'All four in series', 'Three in parallel, in series with the fourth'], 'Each series pair is C/2; two in parallel give C. (Two parallel pairs in series also give C.)', ['C1: series pair C/2', 'C1: two in parallel give C'])
N('M', 3, 'A 5.0 µF capacitor is connected in parallel with a branch of two 10 µF capacitors in series, across 15 V. Calculate the charge on one of the 10 µF capacitors, in µC.', 5.0 * 15, 'µC',
  'The series branch is 5.0 µF with 15 V across it: Q = 5.0 × 10⁻⁶ × 15 = 7.5 × 10⁻⁵ C on each capacitor in it. In µC: 7.5 × 10⁻⁵ × 10⁶ = 75', ['C1: branch C = 5.0 µF', 'C1: Q = CV for the branch'], sig=2, aq='Q')
# hard
N('H', 6, 'In a network, C₁ = 2.0 µF and C₂ = 3.0 µF are in parallel; this pair is in series with C₃ = 10 µF; and the whole branch is in parallel with C₄ = 1.0 µF. The network is connected across 12 V. (a) Calculate the combined capacitance. (b) Calculate the total charge drawn from the supply. (c) Calculate the p.d. across C₃. (d) Calculate the charge on C₂, in µC. Give only the answer to (d).', 3.0 * (12 - ser(5.0, 10) * 12 / 10), 'µC',
  f'(a) C₁ ∥ C₂ = 5.0 µF; with C₃ in series: 5.0 × 10 ÷ 15 = {sf(50 / 15)} µF; plus C₄: {sf(50 / 15 + 1)} µF. (b) Q = {sf(50 / 15 + 1, 4)} × 12 = {sf((50 / 15 + 1) * 12)} µC. (c) The series branch has 12 V: Q_branch = {sf(50 / 15, 4)} × 12 = 40 µC, so V₃ = 40 ÷ 10 = 4.0 V. (d) p.d. across the C₁ ∥ C₂ pair: 12 − 4.0 = 8.0 V. Q₂ = 3.0 × 8.0 = 24 µC',
  ['C1: inner parallel pair', 'C1: series with C₃', 'C1: total C', 'C1: V₃ from branch charge', 'C1: Q₂ = C₂V'], sig=2, aq='Q₂')
N('H', 6, 'A 12 µF capacitor is in series with a parallel pair of an 8.0 µF and a 4.0 µF capacitor, across 20 V. (a) Calculate the combined capacitance. (b) Calculate the charge drawn from the supply. (c) Calculate the p.d. across the parallel pair. (d) Calculate the energy stored in the 8.0 µF capacitor, in mJ. Give only the answer to (d).', 0.5 * 8.0e-6 * 10 ** 2 * 1000, 'mJ',
  '(a) Parallel pair 12 µF; with 12 µF in series: C = 12 ÷ 2 = 6.0 µF. (b) Q = 6.0 × 10⁻⁶ × 20 = 1.2 × 10⁻⁴ C. (c) V = 1.2 × 10⁻⁴ ÷ 12 × 10⁻⁶ = 10 V. (d) W = 0.5 × 8.0 × 10⁻⁶ × 10² = 4.0 × 10⁻⁴ J. In mJ: 4.0 × 10⁻⁴ × 1000 = 0.40',
  ['C1: parallel pair', 'C1: series total', 'C1: Q = CV', 'C1: p.d. across pair', 'C1: W = ½CV²'], sig=2, aq='W')
N('H', 5, 'Identical 10 µF capacitors rated at 25 V are available. A network is needed that has a combined capacitance of 10 µF and can safely be used at 50 V. (a) Explain why a single capacitor will not do. (b) Describe a suitable network and state how many capacitors it uses. (c) Calculate the energy stored by the network at 50 V, in mJ. Give only the answer to (c).', 0.5 * 10e-6 * 50 ** 2 * 1000, 'mJ',
  '(a) A single capacitor would have 50 V across it, twice its rating. (b) Two series pairs connected in parallel: four capacitors; each pair shares 50 V as 25 V each, and gives 5.0 µF, so the two pairs give 10 µF. (c) W = 0.5 × 10 × 10⁻⁶ × 50² = 0.0125 J. In mJ: 0.0125 × 1000 = 12.5',
  ['B1: rating exceeded', 'B1: two series pairs in parallel', 'C1: four capacitors, 25 V each', 'C1: W = ½CV²'], aq='W')
N('H', 6, 'A 4.0 µF capacitor C₁ is charged to 12 V and disconnected. It is then connected across a series pair of uncharged capacitors, C₂ = 6.0 µF and C₃ = 3.0 µF. (a) Calculate the capacitance of the series pair. (b) Calculate the final p.d. across C₁. (c) Calculate the final p.d. across C₃. Give only the answer to (b).', 4.0 * 12 / (4.0 + ser(6.0, 3.0)), 'V',
  '(a) C = 6.0 × 3.0 ÷ 9.0 = 2.0 µF. (b) Charge 4.0 × 12 = 48 µC is shared between C₁ and the 2.0 µF pair in parallel: V = 48 ÷ (4.0 + 2.0) = 8.0 V. (c) The pair carries 2.0 × 8.0 = 16 µC, so V₃ = 16 ÷ 3.0 = 5.3 V.',
  ['C1: series pair', 'M1: charge conserved', 'C1: shared over 6.0 µF', 'C1: charge on pair', 'C1: V₃'], sig=2, aq='V')
N('H', 5, 'An unknown capacitor X is connected in series with a 4.7 µF capacitor, and a meter shows a combined capacitance of 3.1 µF. (a) Calculate X, in µF. (b) Capacitors have a tolerance of ±10 %. Explain how this affects your confidence in the value of X. Give only the answer to (a).', 1 / (1 / 3.1 - 1 / 4.7), 'µF',
  f'(a) 1/X = 1/3.1 − 1/4.7, so X = 1 ÷ (1/3.1 − 1/4.7) = {sf(1 / (1 / 3.1 - 1 / 4.7))} µF. (b) A small change in the 4.7 µF value makes a large change in the difference of reciprocals, so X is quite uncertain.',
  ['M1: reciprocal rule rearranged', 'C1: substitution', 'C1: value', 'B1: uncertainty amplified by subtraction'], aq='X')
N('H', 6, 'A 3.0 µF capacitor C₁ is in series with a parallel pair of a 2.0 µF capacitor C₂ and an unknown capacitor C₃. The network is connected to a 10 V supply, and the p.d. across C₁ is 6.0 V. (a) Calculate the charge on C₁. (b) Calculate the p.d. across the parallel pair. (c) Calculate C₃, in µF. Give only the answer to (c).', 3.0 * 6.0 / (10 - 6.0) - 2.0, 'µF',
  '(a) Q = 3.0 × 10⁻⁶ × 6.0 = 1.8 × 10⁻⁵ C. (b) 10 − 6.0 = 4.0 V. (c) The pair carries 1.8 × 10⁻⁵ C at 4.0 V, so C₂ + C₃ = 1.8 × 10⁻⁵ ÷ 4.0 = 4.5 × 10⁻⁶ F. C₃ = 4.5 − 2.0 = 2.5 µF',
  ['C1: Q = CV', 'C1: p.d.s add', 'M1: same charge on pair as on C₁', 'C1: pair capacitance', 'C1: subtract C₂'], sig=2, aq='C₃')
N('H', 7, 'In a network, C₁ = 6.0 µF is in series with C₂ = 3.0 µF; this pair is in parallel with C₃ = 4.0 µF; and the whole block is in series with C₄ = 12 µF. The network is connected to a 24 V supply. (a) Calculate the combined capacitance. (b) Calculate the charge drawn from the supply. (c) Calculate the p.d. across C₄ and across the block. (d) Calculate the p.d. across C₁. (e) Calculate the total energy stored. Give only the answer to (d).', ser(6.0, 3.0) * (24 - 96 / 12) / 6.0, 'V',
  f'(a) C₁, C₂ in series: 2.0 µF; with C₃: 6.0 µF; with C₄ in series: 6.0 × 12 ÷ 18 = 4.0 µF. (b) Q = 4.0 × 24 = 96 µC. (c) V₄ = 96 ÷ 12 = 8.0 V; block: 24 − 8.0 = 16 V. (d) The C₁–C₂ branch carries 2.0 × 16 = 32 µC, so V₁ = 32 ÷ 6.0 = {sf(32 / 6)} V. (e) W = 0.5 × 4.0 × 10⁻⁶ × 24² = {sf(0.5 * 4e-6 * 576)} J',
  ['C1: series pair', 'C1: block', 'C1: total C', 'C1: Q and V₄', 'M1: branch charge from block p.d.', 'C1: total energy'], aq='V₁')

# ═════════════════════════ 23.7 Discharging a capacitor (14/19/12) ═════════════════════════
lesson('23.7')
M('E', 1, 'A charged capacitor discharges through a resistor. Which describes the graph of current against time?', 'An exponential decay curve', ['A straight line falling to zero', 'A constant current', 'A curve that rises to a maximum'], 'I = I₀e^(−t/RC): the current falls by the same fraction in each equal time interval.')
N('E', 2, 'A 2200 µF capacitor discharges through a 1.0 kΩ resistor. Calculate the time constant.', 2200e-6 * 1.0e3, 's',
  'τ = RC = 1000 × 2200 × 10⁻⁶ = 2.2 s', ['C1: τ = RC'], sig=2, aq='τ')
M('E', 1, 'What is the time constant of a discharging capacitor circuit?', 'The time for the charge to fall to 1/e (about 37 %) of its initial value', ['The time for the charge to fall to zero', 'The time for the charge to halve', 'The time for the charge to fall to 63 % of its initial value'], 'At t = RC, Q = Q₀e⁻¹ ≈ 0.37Q₀.')
N('E', 2, 'What fraction of its initial charge remains on a discharging capacitor after two time constants?', exp(-2), None,
  f'Q/Q₀ = e^(−2) = {sf(exp(-2))}', ['C1: Q/Q₀ = e^(−t/RC)'], aq='fraction')
N('E', 2, 'The instant a capacitor charged to 6.0 V begins discharging through a 1.5 kΩ resistor, what current flows, in mA?', 6.0 / 1.5e3 * 1000, 'mA',
  'I₀ = V₀/R = 6.0 ÷ 1500 = 4.0 × 10⁻³ A. In mA: 4.0 × 10⁻³ × 1000 = 4.0', ['C1: I₀ = V₀/R'], sig=2, aq='I₀')
M('E', 1, 'The resistance through which a capacitor discharges is increased. What happens?', 'The capacitor discharges more slowly', ['The capacitor discharges more quickly', 'The initial charge increases', 'The discharge rate is unchanged'], 'τ = RC increases, so the decay is slower.')
N('E', 2, 'A capacitor initially holds 4.0 mC. Calculate the charge remaining after one time constant, in mC.', 4.0 * exp(-1), 'mC',
  f'Q = Q₀e^(−1) = 4.0 × e^(−1) = {sf(4 * exp(-1))} mC', ['C1: Q = Q₀e⁻¹'], aq='Q')
M('E', 1, 'What is the unit of the product RC?', 's', ['Ω F⁻¹', 'C V⁻¹', 'A'], 'Ω × F = (V A⁻¹)(C V⁻¹) = C A⁻¹ = s.')
N('E', 2, 'A 47 µF capacitor in a sensor circuit drains through a 220 kΩ resistor. What is RC for this circuit?', 47e-6 * 220e3, 's',
  f'τ = RC = 220 × 10³ × 47 × 10⁻⁶ = {sf(220e3 * 47e-6)} s', ['C1: τ = RC with prefixes converted'], aq='τ')
M('E', 1, 'For a discharging capacitor, what does a graph of ln(V) against t look like?', 'A straight line with gradient −1/RC', ['A straight line with gradient −RC', 'An exponential curve', 'A horizontal line'], 'V = V₀e^(−t/RC) gives ln V = ln V₀ − t/RC.')
N('E', 2, 'A discharge circuit has a time constant of 5.0 s. Calculate the time for the charge to halve.', 5.0 * log(2), 's',
  f't½ = RC ln 2 = 5.0 × ln 2 = {sf(5 * log(2))} s', ['C1: t½ = RC ln 2'], aq='t½')
M('E', 1, 'In each 2.0 s interval, a discharging capacitor loses 30 % of the charge it had at the start of that interval. Which statement is correct?', 'The discharge is exponential', ['The capacitor will be empty after about 7 s', 'The current is constant', 'The charge falls linearly'], 'Losing a constant fraction in equal time intervals is the property of exponential decay.')
N('E', 1, 'Engineers often treat a capacitor as fully discharged after 5RC. What fraction of its charge is actually left then?', exp(-5), None,
  f'Q/Q₀ = e^(−5) = {sf(exp(-5))}', [], aq='fraction')
M('E', 1, 'During the discharge of a capacitor through a resistor, how do the current and the p.d. across the capacitor change?', 'Both decay exponentially with the same time constant', ['The p.d. stays constant while the current falls', 'The current rises while the p.d. falls', 'Both fall linearly'], 'I = V/R at every instant, so both follow e^(−t/RC).')
# medium
N('M', 3, 'A 470 µF capacitor charged to 9.0 V discharges through a 10 kΩ resistor. Calculate the p.d. across it after 3.0 s.', 9.0 * exp(-3.0 / 4.7), 'V',
  f'RC = 10 × 10³ × 470 × 10⁻⁶ = 4.7 s. V = 9.0 × e^(−3.0/4.7) = {sf(9 * exp(-3 / 4.7))} V', ['C1: RC', 'C1: V = V₀e^(−t/RC)'], aq='V')
N('M', 3, 'A capacitor discharges from 12 V through a resistor with a time constant of 2.2 s. Calculate the time for the p.d. to fall to 2.0 V.', 2.2 * log(6), 's',
  f'V/V₀ = e^(−t/RC) gives t = RC ln(V₀/V) = 2.2 × ln 6 = {sf(2.2 * log(6))} s', ['C1: take natural logs', 'C1: t = RC ln(V₀/V)'], aq='t')
N('M', 4, 'A 100 µF capacitor discharges through a resistor. Its p.d. falls from 10 V to 5.0 V in 6.9 s. Calculate the resistance, in kΩ.', 6.9 / log(2) / 100e-6 / 1000, 'kΩ',
  f'Half-life: t½ = RC ln 2, so RC = 6.9 ÷ ln 2 = {sf(6.9 / log(2))} s. R = {sf(6.9 / log(2), 4)} ÷ 100 × 10⁻⁶ = {sf(6.9 / log(2) / 1e-4)} Ω. In kΩ: {sf(6.9 / log(2) / 1e-4, 4)} ÷ 1000 = {sf(6.9 / log(2) / 1e-4 / 1000)}', ['M1: t½ = RC ln 2', 'C1: RC', 'C1: R = RC/C'], aq='R')
M('M', 3, 'The capacitance in a discharge circuit is doubled and the resistance is halved. What happens to the time constant?', 'It stays the same', ['It doubles', 'It halves', 'It quadruples'], 'τ = RC, and doubling C while halving R leaves the product unchanged.', ['C1: τ = RC', 'C1: product unchanged'])
N('M', 3, 'The initial discharge current of a capacitor is 2.0 mA and the time constant is 4.0 s. Calculate the current after 5.0 s, in mA.', 2.0 * exp(-5.0 / 4.0), 'mA',
  f'I = I₀e^(−t/RC) = 2.0 × e^(−5.0/4.0) = {sf(2 * exp(-1.25))} mA', ['C1: I = I₀e^(−t/RC)', 'C1: substitution'], aq='I')
N('M', 3, 'A 220 µF capacitor discharges through a 47 kΩ resistor. Calculate the percentage of the initial charge remaining after 10 s.', exp(-10 / (47e3 * 220e-6)) * 100, '%',
  f'RC = 47 × 10³ × 220 × 10⁻⁶ = {sf(47e3 * 220e-6)} s. Q/Q₀ = e^(−10/{sf(47e3 * 220e-6, 4)}) = {sf(exp(-10 / (47e3 * 220e-6)), 4)}. Percentage: {sf(exp(-10 / (47e3 * 220e-6)), 4)} × 100 = {sf(exp(-10 / (47e3 * 220e-6)) * 100)} %', ['C1: RC', 'C1: e^(−t/RC)'], aq='percentage')
M('M', 3, 'What fraction of the initial stored energy remains in a discharging capacitor after one time constant?', 'About 0.14', ['About 0.37', 'About 0.50', 'About 0.05'], 'W ∝ V², so W/W₀ = (e⁻¹)² = e⁻² ≈ 0.135. 0.37 is the charge fraction.', ['C1: W ∝ V²', 'C1: e⁻²'])
N('M', 4, 'A capacitor discharges with a time constant of 3.0 s. Calculate the time taken for its stored energy to halve.', 3.0 * log(2) / 2, 's',
  f'W ∝ V² ∝ e^(−2t/RC). Setting e^(−2t/RC) = ½ gives t = RC ln 2 ÷ 2 = 3.0 × ln 2 ÷ 2 = {sf(3 * log(2) / 2)} s', ['M1: W ∝ e^(−2t/RC)', 'C1: logs', 'C1: substitution'], aq='t')
N('M', 3, 'A graph of ln(V/V) against t for a discharging capacitor has a gradient of −0.25 s⁻¹. The resistor is 20 kΩ. Calculate the capacitance, in µF.', 1 / 0.25 / 20e3 * 1e6, 'µF',
  'Gradient = −1/RC, so RC = 1 ÷ 0.25 = 4.0 s. C = 4.0 ÷ 20 × 10³ = 2.0 × 10⁻⁴ F. In µF: 2.0 × 10⁻⁴ × 10⁶ = 200', ['M1: gradient = −1/RC', 'C1: C = RC/R'], sig=2, aq='C')
M('M', 3, 'Why does the discharge current of a capacitor decrease with time?', 'As the charge falls, the p.d. across the capacitor falls, so the current V/R falls', ['The resistor warms up and its resistance rises', 'The capacitance decreases', 'Electrons run out in the wires'], 'I = V/R and V = Q/C, so the rate of loss of charge is proportional to the charge left.', ['C1: V falls with Q', 'C1: I = V/R'])
N('M', 3, 'A capacitor initially holds 6.0 mC and discharges through a circuit with RC = 3.0 s. Calculate the initial discharge current, in mA.', 6.0e-3 / 3.0 * 1000, 'mA',
  'I₀ = Q₀/RC = 6.0 × 10⁻³ ÷ 3.0 = 2.0 × 10⁻³ A. In mA: 2.0 × 10⁻³ × 1000 = 2.0', ['C1: I₀ = V₀/R = Q₀/RC', 'C1: conversion'], sig=2, aq='I₀')
N('M', 4, 'How many time constants does it take for the p.d. across a discharging capacitor to fall to 1.0 % of its initial value?', log(100), None,
  f'0.010 = e^(−t/RC), so t/RC = ln 100 = {sf(log(100))}', ['C1: V/V₀ = 0.010', 'M1: natural logs', 'C1: value'], aq='t/RC')
M('M', 3, 'Two identical capacitors discharge through identical resistors, one starting from 12 V and the other from 6.0 V. How do the times for their p.d.s to halve compare?', 'They are the same', ['The 12 V capacitor takes twice as long', 'The 6.0 V capacitor takes twice as long', 'The 12 V capacitor takes four times as long'], 'The half-life RC ln 2 does not depend on the starting value.', ['C1: t½ = RC ln 2', 'C1: independent of V₀'])
N('M', 3, 'A 0.22 F memory-backup capacitor discharges through a 47 kΩ load. Calculate the time constant, in hours.', 0.22 * 47e3 / 3600, 'hours',
  f'RC = 47 × 10³ × 0.22 = {sf(47e3 * 0.22)} s. In hours: {sf(47e3 * 0.22, 4)} ÷ 3600 = {sf(47e3 * 0.22 / 3600)}', ['C1: RC', 'C1: seconds to hours'], aq='τ')
N('M', 3, 'In a camera sensor, a 100 nF capacitor at 5.0 V is drained through 10 kΩ. What is its p.d. 2.0 ms later?', 5.0 * exp(-2.0e-3 / (10e3 * 100e-9)), 'V',
  f'RC = 10 × 10³ × 100 × 10⁻⁹ = 1.0 × 10⁻³ s. V = 5.0 × e^(−2.0) = {sf(5 * exp(-2))} V', ['C1: RC', 'C1: V = V₀e^(−t/RC)'], aq='V')
M('M', 4, 'How is the half-life t½ of a capacitor discharge related to the time constant RC?', 't½ = RC ln 2 ≈ 0.69RC', ['t½ = RC/2', 't½ = 2RC', 't½ = RC'], 'Setting Q = Q₀/2 in Q = Q₀e^(−t/RC) gives t = RC ln 2.', ['C1: Q = Q₀/2', 'C1: logs', 'C1: ln 2 ≈ 0.69'])
N('M', 3, 'A capacitor initially holding 5.0 mC discharges through a resistor. Calculate the charge that flows through the resistor during the first time constant, in mC.', 5.0 * (1 - exp(-1)), 'mC',
  f'Remaining: 5.0e⁻¹; flowed = 5.0 × (1 − e^(−1)) = {sf(5 * (1 - exp(-1)))} mC', ['C1: Q = Q₀e⁻¹ remaining', 'C1: difference'], aq='ΔQ')
N('M', 4, 'A 1000 µF capacitor charged to 20 V discharges completely through a resistor. Calculate the total energy dissipated in the resistor.', 0.5 * 1000e-6 * 20 ** 2, 'J',
  'All the stored energy is converted to heat: W = 0.5 × 1000 × 10⁻⁶ × 20² = 0.20 J', ['B1: all stored energy dissipated', 'C1: W = ½CV²', 'C1: substitution'], sig=2, aq='W')
M('M', 3, 'A high-resistance digital voltmeter (10 MΩ) is connected across a charged 1.0 µF capacitor. Why does its reading slowly fall?', 'The capacitor discharges through the voltmeter with a time constant of about 10 s', ['The voltmeter charges the capacitor further', 'The capacitance decreases with time', 'The meter\'s battery is running down'], 'RC = 10 × 10⁶ × 1.0 × 10⁻⁶ = 10 s, so the reading decays noticeably within seconds.', ['C1: meter provides discharge path', 'C1: RC ≈ 10 s'])
# hard
N('H', 6, 'A capacitor discharges through a 100 kΩ resistor. The p.d. is recorded: t/s = 0, 10, 20, 30, 40 and V/V = 12.0, 7.3, 4.4, 2.7, 1.6. (a) Explain why a graph of ln(V/V) against t should be a straight line. (b) Calculate the gradient using the first and last readings. (c) Calculate the time constant. (d) Calculate the capacitance, in µF. Give only the answer to (d).', 40 / (log(12.0) - log(1.6)) / 100e3 * 1e6, 'µF',
  f'(a) V = V₀e^(−t/RC), so ln V = ln V₀ − t/RC: linear in t. (b) Gradient = (ln 1.6 − ln 12.0) ÷ 40 = {sf((log(1.6) - log(12)) / 40)} s⁻¹. (c) RC = −1 ÷ gradient = 40 ÷ (ln 12.0 − ln 1.6) = {sf(40 / (log(12) - log(1.6)))} s. (d) C = {sf(40 / (log(12) - log(1.6)), 4)} ÷ 100 × 10³ = {sf(40 / (log(12) - log(1.6)) / 1e5)} F. In µF: {sf(40 / (log(12) - log(1.6)) / 1e5, 4)} × 10⁶ = {sf(40 / (log(12) - log(1.6)) / 1e5 * 1e6)}',
  ['B1: ln V linear in t', 'C1: gradient', 'M1: gradient = −1/RC', 'C1: RC', 'C1: C = RC/R'], aq='C')
N('H', 5, 'The p.d. across a 470 µF capacitor discharging through a resistor halves every 3.5 s. (a) Show that the half-life is RC ln 2. (b) Calculate the time constant. (c) Calculate the resistance, in kΩ. Give only the answer to (c).', 3.5 / log(2) / 470e-6 / 1000, 'kΩ',
  f'(a) V₀/2 = V₀e^(−t/RC) gives t = RC ln 2. (b) RC = 3.5 ÷ ln 2 = {sf(3.5 / log(2))} s. (c) R = {sf(3.5 / log(2), 4)} ÷ 470 × 10⁻⁶ = {sf(3.5 / log(2) / 470e-6)} Ω. In kΩ: {sf(3.5 / log(2) / 470e-6, 4)} ÷ 1000 = {sf(3.5 / log(2) / 470e-6 / 1000)}',
  ['M1: half-life from exponential', 'C1: RC = t½/ln 2', 'C1: R = RC/C', 'C1: conversion to kΩ'], aq='R')
N('H', 6, 'A defibrillator capacitor of 32 µF is charged to 5.0 kV and discharges through a patient\'s chest, of resistance 50 Ω. (a) Calculate the time constant, in ms. (b) Calculate the initial current. (c) Calculate the energy delivered to the patient in the first 2.0 ms. Give only the answer to (c).', 0.5 * 32e-6 * 5.0e3 ** 2 * (1 - exp(-2 * 2.0e-3 / (50 * 32e-6))), 'J',
  f'(a) RC = 50 × 32 × 10⁻⁶ = 1.6 × 10⁻³ s, which is 1.6 ms. (b) I₀ = 5.0 × 10³ ÷ 50 = 100 A. (c) W₀ = 0.5 × 32 × 10⁻⁶ × (5.0 × 10³)² = 400 J. W ∝ V², so the energy left is W₀e^(−2t/RC) and the energy delivered = 400 × (1 − e^(−2 × 2.0/1.6)) = {sf(400 * (1 - exp(-2.5)))} J',
  ['C1: RC', 'C1: I₀ = V₀/R', 'C1: W₀ = ½CV²', 'M1: W ∝ e^(−2t/RC)', 'C1: energy delivered'], aq='W')
N('H', 5, '(a) Starting from Q = Q₀e^(−t/RC), show that ln Q = ln Q₀ − t/RC. (b) A 220 µF capacitor discharges through a 15 kΩ resistor. Calculate the time taken for it to lose 75 % of its charge. Give only the answer to (b).', 15e3 * 220e-6 * log(4), 's',
  f'(a) Taking natural logs: ln Q = ln Q₀ + ln e^(−t/RC) = ln Q₀ − t/RC. (b) RC = 15 × 10³ × 220 × 10⁻⁶ = 3.3 s. 25 % remains: 0.25 = e^(−t/RC), so t = 3.3 × ln 4 = {sf(3.3 * log(4))} s',
  ['B1: logs taken correctly', 'C1: RC', 'M1: 25 % remains', 'C1: t = RC ln 4'], aq='t')
N('H', 5, 'A timer circuit switches a light off when the p.d. across a discharging 1000 µF capacitor falls from 9.0 V to 3.0 V. The delay must be 60 s. (a) Show that the delay is RC ln 3. (b) Calculate the resistance needed, in kΩ. (c) Suggest why the actual delay might differ from 60 s. Give only the answer to (b).', 60 / log(3) / 1000e-6 / 1000, 'kΩ',
  f'(a) V/V₀ = e^(−t/RC) with V₀/V = 3, so t = RC ln 3. (b) RC = 60 ÷ ln 3 = {sf(60 / log(3))} s. R = {sf(60 / log(3), 4)} ÷ 1000 × 10⁻⁶ = {sf(60 / log(3) / 1e-3)} Ω. In kΩ: {sf(60 / log(3) / 1e-3, 4)} ÷ 1000 = {sf(60 / log(3) / 1e-3 / 1000)}. (c) Capacitors have a wide tolerance (often ±20 %) and can leak, and the switching p.d. may vary.',
  ['M1: V/V₀ = 1/3', 'C1: RC', 'C1: R in kΩ', 'B1: tolerance or leakage'], aq='R')
N('H', 6, 'A 100 µF capacitor charged to 10 V discharges through a 20 kΩ resistor for 2.0 s. The resistor is then switched to 5.0 kΩ and the discharge continues. (a) Calculate the p.d. after the first 2.0 s. (b) Calculate the new time constant. (c) Calculate the p.d. 1.0 s after the switch. Give only the answer to (c).', 10 * exp(-2.0 / 2.0) * exp(-1.0 / 0.50), 'V',
  f'(a) RC₁ = 20 × 10³ × 100 × 10⁻⁶ = 2.0 s; V = 10 × e^(−1) = {sf(10 * exp(-1))} V. (b) RC₂ = 5.0 × 10³ × 100 × 10⁻⁶ = 0.50 s. (c) V = {sf(10 * exp(-1), 4)} × e^(−1.0/0.50) = {sf(10 * exp(-1) * exp(-2))} V',
  ['C1: first RC', 'C1: V after 2.0 s', 'C1: second RC', 'M1: new decay starts from the p.d. at the switch', 'C1: final V'], aq='V')
N('H', 5, 'Because its dielectric is not a perfect insulator, an isolated 4.7 µF capacitor loses half its p.d. in 2.0 hours. (a) Calculate the time constant. (b) Calculate the leakage resistance, in GΩ. Give only the answer to (b).', 7200 / log(2) / 4.7e-6 / 1e9, 'GΩ',
  f'(a) RC = t½ ÷ ln 2 = 7200 ÷ ln 2 = {sf(7200 / log(2))} s. (b) R = {sf(7200 / log(2), 4)} ÷ 4.7 × 10⁻⁶ = {sf(7200 / log(2) / 4.7e-6)} Ω. In GΩ: {sf(7200 / log(2) / 4.7e-6, 4)} ÷ 10⁹ = {sf(7200 / log(2) / 4.7e-6 / 1e9)}',
  ['C1: hours to seconds', 'M1: RC = t½/ln 2', 'C1: R = RC/C', 'C1: conversion to GΩ'], aq='R')
N('H', 6, 'A capacitor initially charged to 9.0 V discharges through a resistor. The current is 0.50 mA at the start and 0.18 mA after 20 s. (a) Calculate the time constant. (b) Calculate the initial charge, using Q₀ = I₀RC. (c) Calculate the capacitance, in µF. Give only the answer to (c).', 0.50e-3 * 20 / log(0.50 / 0.18) / 9.0 * 1e6, 'µF',
  f'(a) I = I₀e^(−t/RC), so RC = t ÷ ln(I₀/I) = 20 ÷ ln(0.50/0.18) = {sf(20 / log(0.5 / 0.18))} s. (b) Q₀ = 0.50 × 10⁻³ × {sf(20 / log(0.5 / 0.18), 4)} = {sf(0.5e-3 * 20 / log(0.5 / 0.18))} C. (c) C = Q₀/V₀ = {sf(0.5e-3 * 20 / log(0.5 / 0.18), 4)} ÷ 9.0 = {sf(0.5e-3 * 20 / log(0.5 / 0.18) / 9)} F. In µF: {sf(0.5e-3 * 20 / log(0.5 / 0.18) / 9, 4)} × 10⁶ = {sf(0.5e-3 * 20 / log(0.5 / 0.18) / 9 * 1e6)}',
  ['C1: logs of current ratio', 'C1: RC', 'M1: Q₀ = I₀RC', 'C1: C = Q₀/V₀', 'C1: conversion to µF'], aq='C')
N('H', 5, 'A 470 µF capacitor charged to 12 V discharges through a 1.0 kΩ resistor. (a) Calculate the initial power dissipated in the resistor. (b) Show that the power falls as e^(−2t/RC). (c) Calculate the power after one time constant, in mW. Give only the answer to (c).', 12 ** 2 / 1000 * exp(-2) * 1000, 'mW',
  f'(a) P₀ = V₀²/R = 12² ÷ 1000 = 0.144 W. (b) P = V²/R and V ∝ e^(−t/RC), so P ∝ e^(−2t/RC). (c) P = 0.144 × e^(−2) = {sf(0.144 * exp(-2))} W. In mW: {sf(0.144 * exp(-2), 4)} × 1000 = {sf(0.144 * exp(-2) * 1000)}',
  ['C1: P = V²/R', 'B1: P ∝ e^(−2t/RC)', 'C1: e⁻² factor', 'C1: conversion to mW'], aq='P')
N('H', 5, '(a) Show that the product RC has the unit of seconds. (b) A discharging capacitor has RC = 2.0 s. Calculate the time taken for its p.d. to fall by 20 %. (c) Calculate the fraction of the initial energy remaining at that time. Give only the answer to (b).', 2.0 * log(1 / 0.80), 's',
  f'(a) Ω × F = (V A⁻¹)(C V⁻¹) = C A⁻¹ = (A s) A⁻¹ = s. (b) V = 0.80V₀, so t = RC ln(1/0.80) = 2.0 × ln 1.25 = {sf(2 * log(1.25))} s. (c) W ∝ V², so the fraction = 0.80² = 0.64.',
  ['B1: units shown', 'M1: V/V₀ = 0.80', 'C1: t = RC ln(1/0.80)', 'C1: energy fraction 0.64'], aq='t')
N('H', 6, 'A student measures the time t½ for the p.d. across a capacitor to fall from 10 V to 5.0 V using different resistors: R/kΩ = 10, 20, 30, 40 and t½/s = 0.70, 1.38, 2.08, 2.77. (a) Explain why a graph of t½ against R is a straight line through the origin. (b) Calculate the gradient using the first and last readings. (c) Calculate the capacitance, in µF. Give only the answer to (c).', (2.77 - 0.70) / 30e3 / log(2) * 1e6, 'µF',
  f'(a) t½ = RC ln 2, so t½ ∝ R with gradient C ln 2. (b) Gradient = (2.77 − 0.70) ÷ ((40 − 10) × 10³) = {sf(2.07 / 30e3)} s Ω⁻¹. (c) C = gradient ÷ ln 2 = {sf(2.07 / 30e3, 4)} ÷ ln 2 = {sf(2.07 / 30e3 / log(2))} F. In µF: {sf(2.07 / 30e3 / log(2), 4)} × 10⁶ = {sf(2.07 / 30e3 / log(2) * 1e6)}',
  ['M1: t½ = RC ln 2', 'B1: proportional to R', 'C1: gradient', 'C1: C = gradient/ln 2', 'C1: conversion to µF'], aq='C')
N('H', 6, 'In a pacemaker, a 2.0 µF capacitor charged to 5.0 V discharges through heart tissue of resistance 500 Ω. The pulse ends when the p.d. has fallen to 1.0 V. (a) Calculate the time constant. (b) Calculate the duration of the pulse, in ms. (c) Calculate the charge delivered during the pulse, in µC. Give only the answer to (b).', 500 * 2.0e-6 * log(5) * 1000, 'ms',
  f'(a) RC = 500 × 2.0 × 10⁻⁶ = 1.0 × 10⁻³ s. (b) V₀/V = 5, so t = RC ln 5 = 1.0 × 10⁻³ × ln 5 = {sf(1e-3 * log(5))} s. In ms: {sf(1e-3 * log(5), 4)} × 1000 = {sf(log(5))}. (c) ΔQ = C × ΔV = 2.0 × 10⁻⁶ × (5.0 − 1.0) = 8.0 × 10⁻⁶ C, which is 8.0 µC.',
  ['C1: RC', 'M1: V/V₀ = 1/5', 'C1: t = RC ln 5', 'C1: conversion to ms', 'C1: ΔQ = CΔV'], aq='t')
